-- LEGACY ONLY: do not execute this against a database created with Alembic.
-- The initial Alembic revision already creates these tables. This SQL remains
-- solely as a reviewable MySQL rollout for installations created before the
-- reviews/recommendations extension.
CREATE TABLE reviews (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, product_id INT NOT NULL, order_id INT NOT NULL, rating INT NOT NULL, title VARCHAR(140) NOT NULL, comment TEXT NOT NULL, verified_purchase BOOLEAN NOT NULL DEFAULT TRUE, status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'APPROVED', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT ck_review_rating_range CHECK (rating BETWEEN 1 AND 5), CONSTRAINT uq_review_per_order_product UNIQUE (user_id,product_id,order_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, INDEX ix_review_product_status(product_id,status));
CREATE TABLE review_helpful_votes (id INT AUTO_INCREMENT PRIMARY KEY, review_id INT NOT NULL, user_id INT NOT NULL, vote BOOLEAN NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT uq_helpful_vote UNIQUE(review_id,user_id), FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE review_reports (id INT AUTO_INCREMENT PRIMARY KEY, review_id INT NOT NULL, user_id INT NOT NULL, reason VARCHAR(40) NOT NULL, description TEXT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, CONSTRAINT uq_review_report UNIQUE(review_id,user_id), FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX ix_report_status(status));
CREATE TABLE user_interactions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, product_id INT NOT NULL, event_type ENUM('VIEW','ADD_TO_CART','PURCHASE','RATING','WISHLIST') NOT NULL, created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, INDEX ix_interaction_user_event(user_id,event_type), INDEX ix_interaction_product_event(product_id,event_type));
